const raw = $input.first().json;
let data = raw;

// Lecture body si payload encapsulé
if (raw.body !== undefined) {
  let rawBody = raw.body;

  if (typeof rawBody === 'string') {
    rawBody = rawBody.replace(/^=+/, '').trim();

    try {
      data = JSON.parse(rawBody);
    } catch (e) {
      data = raw;
    }

  } else if (typeof rawBody === 'object' && rawBody !== null) {
    data = rawBody;
  }
}

// Valeurs par défaut
const task_id =
  data.task_id ||
  data.body?.task_id ||
  `TASK-DAST-${Date.now()}`;

const environment =
  data.environment ||
  data.body?.environment ||
  'staging';

const target_url =
  data.target_url ||
  data.target?.url ||
  `https://app-${environment}.monprojet.com`;

const endpoints =
  data.endpoints ||
  data.target?.endpoints ||
  ['/api/users', '/api/auth/login', '/health'];

// DAST dynamique interdit en production (bonne pratique : pas de tests intrusifs sur la prod).
// On NE bloque PAS le pipeline : on saute proprement l analyse et on renvoie PASS.
const _dastSkipped = String(environment).toLowerCase() === 'production';

return [
  {
    json: {
      task_id: String(task_id),
      agent: 'Agent DAST',
      project_id: String(data.project_id || task_id),
      app_type: String(data.app_type || 'web'),
      target_url: String(target_url),
      environment: String(environment),
      endpoints: endpoints,
      endpoints_json: JSON.stringify(endpoints),
      endpoints_count: String(endpoints.length),
      auth_type: String(data.auth?.type || 'none'),
      auth_token: String(data.auth?.token || ''),
      simulate: _dastSkipped ? 'pass' : String(data.simulate || 'pass'),
      dast_skipped: _dastSkipped,
      server_js: String(data.server_js || ''),
      status: String(data.status || ''),
      summary: data.summary || {},
      findings: data.findings || [],
      timestamp: data.timestamp || new Date().toISOString()
    }
  }
];

// =========================
// AGENT DAST — FINAL (100% JS DÉTERMINISTE)
// =========================

const input = $input.first().json;

const url = (input.target_url || "").toLowerCase();
const simulate = (input.simulate || "").toLowerCase();

let critical = [];
let warnings = [];

// -------- MODES --------
const isFail = simulate === "fail" 
  || url.includes("vulnerable") 
  || url.includes("insecure");

const isWarn = simulate === "warn";

// -------- VULN DB --------
const vulns = [
  {
    name: "SQL Injection",
    severity: "critical",
    msg: "SQL Injection possible sur /api/users"
  },
  {
    name: "Broken Authentication",
    severity: "critical",
    msg: "Endpoint admin accessible sans authentification"
  },
  {
    name: "XSS",
    severity: "high",
    msg: "Injection XSS possible"
  },
  {
    name: "Security Headers",
    severity: "medium",
    msg: "Headers de sécurité manquants"
  }
];

// -------- ANALYSE --------
if (isFail) {
  for (const v of vulns) {
    if (v.severity === "critical") {
      critical.push(v.msg);
    } else {
      warnings.push(v.msg);
    }
  }
} else if (isWarn) {
  warnings.push("Headers de sécurité partiellement configurés");
}
// sinon → PASS pur (aucun warning)

// -------- ANALYSE DU VRAI CODE (DAST base sur le code genere) --------
var _code = String(input.server_js || "");
if (String(input.dast_skipped) !== "true" && input.dast_skipped !== true && _code.length > 50) {
  critical = [];
  warnings = [];
  function _has(re){ return re.test(_code); }
  var _checks = [
    { ok: _has(/authMiddleware/),                                                    sev: "c", msg: "A01 Broken Access Control : authMiddleware absent des routes" },
    { ok: _has(/user_id/) && _has(/WHERE[\s\S]{0,60}user_id/i),                       sev: "c", msg: "A01 Isolation par utilisateur (user_id) absente" },
    { ok: _has(/\.prepare\(/),                                                        sev: "c", msg: "A03 Injection SQL : requetes non parametrees" },
    { ok: _has(/contentSecurityPolicy:\s*\{/) && !_has(/contentSecurityPolicy:\s*false/), sev: "h", msg: "A05 Security Misconfiguration : CSP absente ou desactivee" },
    { ok: _has(/helmet\(/),                                                           sev: "h", msg: "A05 En-tetes de securite (helmet) absents" },
    { ok: _has(/httpOnly:\s*true/),                                                   sev: "h", msg: "A07 Cookie de session sans attribut HttpOnly" },
    { ok: _has(/sameSite/),                                                           sev: "w", msg: "A07 Cookie de session sans attribut SameSite" },
    { ok: _has(/rateLimit\(/),                                                        sev: "w", msg: "A07 Rate-limiting absent (brute-force)" },
    { ok: _has(/validationResult|express-validator/),                                sev: "w", msg: "A03 Validation des entrees absente" },
    { ok: _has(/JWT_SECRET/) && _has(/randomBytes/),                                  sev: "h", msg: "A02 Secret JWT potentiellement code en dur" }
  ];
  _checks.forEach(function(ch){ if (!ch.ok) { if (ch.sev === "c" || ch.sev === "h") critical.push(ch.msg); else warnings.push(ch.msg); } });
}

// -------- DEDUP --------
critical = [...new Set(critical)];
warnings = [...new Set(warnings)];

// -------- SCORING --------
let securityScore = 100;
securityScore -= critical.length * 30;
securityScore -= warnings.length * 10;
if (securityScore < 0) securityScore = 0;

const qualityScore = warnings.length > 0 ? 70 : 100;

const globalscore = Math.round(
  (securityScore * 0.8) + (qualityScore * 0.2)
);

// -------- STATUS --------
let status = "PASS";

if (critical.length > 0) {
  status = "FAIL";
} else if (warnings.length > 0) {
  status = "NEEDSIMPROVEMENT";
}

// -------- NORMALISATION --------
status = String(status)
  .replace(/\s+/g, "")
  .trim()
  .toUpperCase();

// -------- HARD GUARD --------
const allowed = ["PASS", "FAIL", "NEEDSIMPROVEMENT"];
if (!allowed.includes(status)) {
  status = "FAIL";
  critical.push("Invalid status computed");
}

// -------- SKIP PRODUCTION --------
const _skipped = input.dast_skipped === true || input.dast_skipped === 'true';
const _summary = _skipped
  ? 'DAST non execute : tests dynamiques interdits en environnement production (reserves a staging).'
  : (critical.length > 0
      ? `${critical.length} vulnérabilité(s) critique(s) détectée(s) sur ${input.target_url}`
      : 'Aucune vulnérabilité DAST détectée');
const _recos = _skipped
  ? ['DAST volontairement non execute en production. Executer les tests dynamiques en staging avant promotion.']
  : (critical.length > 0
      ? ['Corriger immédiatement les vulnérabilités critiques']
      : warnings.length > 0
        ? ['Renforcer la configuration sécurité (headers, CSP, auth)']
        : ['Aucune vulnérabilité détectée']);

// -------- OUTPUT --------
return [{
  json: {
    agent: "Agent DAST",
    task_id: input.task_id || "unknown",
    status,
    global_score: globalscore,
    approved_for_pipeline: status === "PASS",
    language: input.language || "javascript",
    critical_issues: critical,
    warnings,
    recommendations: _recos,
    dimensions: {
      security: { score: securityScore },
      quality: { score: qualityScore }
    },
    summary: _summary,
    dast_skipped: _skipped,
    timestamp: new Date().toISOString()
  }
}];
